def is_square(n):
    if n < 0:
        return False
    root = int(n**0.5)
    return root * root == n

count = 0
candidates = []

# Constraints: 1 <= a <= 20, 1 <= b <= 20
for a in range(1, 21):
    for b in range(1, 21):
        # W3 constraint: a + b must be odd
        if (a + b) % 2 == 0:
            continue

        # Calculate N^2
        try:
            val = (2**a) * (5**b) + 625
        except OverflowError:
            # Values get huge quickly, stopping the search gracefully
            continue 

        if is_square(val):
            N = int(val**0.5)
            count += 1
            candidates.append((a, b, N))

print(f"Found {count} solutions.")
print(f"Candidates: {candidates}")

